import itertools,json,time
from z3 import *
results=[]
for n,w,target in [(6,3,4),(8,3,4),(8,4,5),(10,4,5)]:
 ts=[]
 for a in range(1,min(n,w)+1):
  for A in itertools.combinations(range(n),a):
   for b in range(w-a+1):
    for B in itertools.combinations([i for i in range(n) if i not in A],b):
     ts.append((set(A),set(B)))
 vs=[Bool('x_%d'%i) for i in range(len(ts))];s=Solver();s.set(timeout=30000)
 for i,(A,B) in enumerate(ts):
  for j in range(i):
   Q,D=ts[j]
   if not(A&D or Q&B):s.add(Or(Not(vs[i]),Not(vs[j])))
 for C in itertools.combinations(range(n),target-1):
  C=set(C);s.add(Or([vs[i] for i,(A,B) in enumerate(ts) if not A&C]))
 t=time.time();ans=s.check();rec=dict(n=n,w=w,target=target,terms=len(ts),result=str(ans),sec=time.time()-t)
 if ans==sat:
  m=s.model();rec['chosen']=[(sorted(A),sorted(B)) for i,(A,B) in enumerate(ts) if is_true(m.eval(vs[i]))]
 results.append(rec);print(rec,flush=True)
open('workspace/agent3_hitting_dnf_checks.json','w').write(json.dumps(results,indent=2))

